          {"id": "INV-DAS-CONST-004", "text": "CUSTODY_REQUIREMENT is 4, the minimum number of custody groups an honest node must custody."},
          {"id": "INV-DAS-CONST-005", "text": "SAMPLES_PER_SLOT is 8, the minimum number of samples for an honest node per slot."}
        ],
        "functions": [],
        "state_variables": [
          {"id": "SV-DAS-CONST-001", "name": "UINT256_MAX", "type": "uint256", "value": "2**256 - 1"},
          {"id": "SV-DAS-CONST-002", "name": "NUMBER_OF_COLUMNS", "type": "uint64", "value": "CELLS_PER_EXT_BLOB (= 128)"},
          {"id": "SV-DAS-CONST-003", "name": "SAMPLES_PER_SLOT", "type": "uint64", "value": "8"},
          {"id": "SV-DAS-CONST-004", "name": "NUMBER_OF_CUSTODY_GROUPS", "type": "uint64", "value": "128"},
          {"id": "SV-DAS-CONST-005", "name": "CUSTODY_REQUIREMENT", "type": "uint64", "value": "4"}
