              {"name": "column", "type": "List[Cell, MAX_BLOB_COMMITMENTS_PER_BLOCK]"},
              {"name": "kzg_commitments", "type": "List[KZGCommitment, MAX_BLOB_COMMITMENTS_PER_BLOCK]"},
              {"name": "kzg_proofs", "type": "List[KZGProof, MAX_BLOB_COMMITMENTS_PER_BLOCK]"},
              {"name": "signed_block_header", "type": "SignedBeaconBlockHeader"},
              {"name": "kzg_commitments_inclusion_proof", "type": "Vector[Bytes32, KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH]"}
