        "pre_conditions": [],
        "post_conditions": []
      },
      {
        "id": "SG-DAS-GET-CUSTODY-GROUPS",
        "name": "get_custody_groups Helper",
        "description": "Deterministic, public function that computes which custody groups a node is responsible for, based on the node's ID and the desired custody group count. Uses hash-based pseudo-random selection.",
        "invariants": [
          {"id": "INV-DAS-GCG-001", "text": "The returned custody groups list has exactly custody_group_count unique elements."},
          {"id": "INV-DAS-GCG-002", "text": "The returned list is sorted in ascending order."},
          {"id": "INV-DAS-GCG-003", "text": "Increasing custody_group_count for a given node_id extends (rather than reshuffles) the returned list."},
          {"id": "INV-DAS-GCG-004", "text": "The function is deterministic: same inputs always produce same outputs."}
        ],
        "functions": [
          {
            "id": "FN-DAS-GCG-001",
            "signature": "def get_custody_groups(node_id: NodeID, custody_group_count: uint64) -> Sequence[CustodyIndex]",
            "description": "Returns a sorted list of unique CustodyIndex values pseudo-randomly derived from node_id. If custody_group_count == NUMBER_OF_CUSTODY_GROUPS, returns all groups without computation."
