        "functions": [
          {
            "id": "FN-DAS-CCG-001",
            "signature": "def compute_columns_for_custody_group(custody_group: CustodyIndex) -> Sequence[ColumnIndex]",
            "description": "Returns the list of ColumnIndex values assigned to the given custody group via interleaved mapping."
