        "post_conditions": [
          {"id": "POST-DAS-CCG-001", "text": "len(result) == NUMBER_OF_COLUMNS // NUMBER_OF_CUSTODY_GROUPS"},
          {"id": "POST-DAS-CCG-002", "text": "All returned column indices are in range [0, NUMBER_OF_COLUMNS)"}
        ]
