        "name": "compute_matrix Helper",
        "description": "Computes the full extended data matrix from a sequence of blobs. Each blob is expanded via compute_cells_and_kzg_proofs into cells and proofs, then flattened into MatrixEntry objects indexed by (row=blob_index, column=cell_index).",
        "invariants": [
          {"id": "INV-DAS-CM-001", "text": "The matrix has exactly len(blobs) * NUMBER_OF_COLUMNS entries."},
          {"id": "INV-DAS-CM-002", "text": "Each MatrixEntry's row_index corresponds to the originating blob index and column_index to the cell index."}
        ],
        "functions": [
          {
            "id": "FN-DAS-CM-001",
            "signature": "def compute_matrix(blobs: Sequence[Blob]) -> Sequence[MatrixEntry]",
            "description": "Returns the full flattened sequence of MatrixEntry by computing cells and KZG proofs for each blob."
