          {"id": "INV-DAS-RM-001", "text": "Recovery requires at least 50% of columns per row to succeed."},
          {"id": "INV-DAS-RM-002", "text": "The recovered matrix has exactly blob_count * NUMBER_OF_COLUMNS entries."}
        ],
        "functions": [
          {
            "id": "FN-DAS-RM-001",
            "signature": "def recover_matrix(partial_matrix: Sequence[MatrixEntry], blob_count: uint64) -> Sequence[MatrixEntry]",
            "description": "Recovers the full flattened matrix from a partial matrix by applying erasure coding recovery per blob row."
          }
        ],
        "state_variables": [],
        "data_structures": [],
        "pre_conditions": [
          {"id": "PRE-DAS-RM-001", "text": "partial_matrix contains at least 50% of columns for each row (blob) to enable recovery."}
