    "layer": "consensus",
    "status": "ok",
    "sub_graphs": [
      {
        "id": "SG-FC-IS-DATA-AVAILABLE",
        "name": "Modified is_data_available",
        "description": "Modified data availability check for Fulu that replaces blob retrieval with column sidecar retrieval and verification. Uses retrieve_column_sidecars to get all column sidecars to sample, then verifies each with verify_data_column_sidecar and verify_data_column_sidecar_kzg_proofs.",
        "invariants": [
          {"id": "INV-FC-IDA-001", "text": "Data is considered available only if ALL column sidecars pass both structural verification and KZG proof verification."},
          {"id": "INV-FC-IDA-002", "text": "The p2p network does not guarantee sidecar retrieval outside of MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS epochs."},
          {"id": "INV-FC-IDA-003", "text": "This function replaces the previous blob-based data availability check with column-sidecar-based verification (EIP-7594)."}
        ],
        "functions": [
          {
            "id": "FN-FC-IDA-001",
            "signature": "def is_data_available(beacon_block_root: Root) -> bool",
            "description": "Returns True if all column sidecars for the given block root are retrievable and pass verification (both structural and KZG proof). Replaces blob-based check from prior forks."
          }
        ],
        "state_variables": [],
        "data_structures": [],
        "pre_conditions": [
          {"id": "PRE-FC-IDA-001", "text": "beacon_block_root must reference a known block."}
        ],
        "post_conditions": [
          {"id": "POST-FC-IDA-001", "text": "Returns True only if retrieve_column_sidecars succeeds AND all sidecars pass verify_data_column_sidecar AND verify_data_column_sidecar_kzg_proofs."},
          {"id": "POST-FC-IDA-002", "text": "Returns False or raises exception if any column sidecar is missing or fails verification."}
        ]
      },
      {
        "id": "SG-FC-ON-BLOCK",
        "name": "Modified on_block Handler",
        "description": "Fork choice handler invoked upon receiving a new block. Modified in Fulu (EIP-7594) to call is_data_available without blob_kzg_commitments as input. Validates the block against the store, checks data availability, executes state transition, and updates checkpoints.",
        "invariants": [
          {"id": "INV-FC-OB-001", "text": "Parent block must be known in store.block_states."},
          {"id": "INV-FC-OB-002", "text": "Block slot must not be in the future (get_current_slot(store) >= block.slot)."},
          {"id": "INV-FC-OB-003", "text": "Block slot must be after the finalized epoch slot."},
          {"id": "INV-FC-OB-004", "text": "Block must be a descendant of the finalized checkpoint block."},
          {"id": "INV-FC-OB-005", "text": "Data must be available via is_data_available(hash_tree_root(block)) -- modified in Fulu to use column sidecars."},
          {"id": "INV-FC-OB-006", "text": "State transition must succeed (block is valid)."}
        ],
        "functions": [
          {
            "id": "FN-FC-OB-001",
            "signature": "def on_block(store: Store, signed_block: SignedBeaconBlock) -> None",
            "description": "Processes a new block: validates parent existence, timing, finality, data availability (via column sidecars in Fulu), runs state transition, and updates store with new block state and checkpoints."
          }
        ],
        "state_variables": [],
        "data_structures": [],
        "pre_conditions": [
          {"id": "PRE-FC-OB-001", "text": "block.parent_root in store.block_states"},
          {"id": "PRE-FC-OB-002", "text": "get_current_slot(store) >= block.slot"},
          {"id": "PRE-FC-OB-003", "text": "block.slot > compute_start_slot_at_epoch(store.finalized_checkpoint.epoch)"},
          {"id": "PRE-FC-OB-004", "text": "store.finalized_checkpoint.root == get_checkpoint_block(store, block.parent_root, store.finalized_checkpoint.epoch)"},
          {"id": "PRE-FC-OB-005", "text": "is_data_available(hash_tree_root(block)) == True"}
        ],
        "post_conditions": [
          {"id": "POST-FC-OB-001", "text": "store.blocks[block_root] contains the new block."},
          {"id": "POST-FC-OB-002", "text": "store.block_states[block_root] contains the post-state after state_transition."},
          {"id": "POST-FC-OB-003", "text": "Block timeliness is recorded via record_block_timeliness."},
          {"id": "POST-FC-OB-004", "text": "Proposer boost root is updated."},
          {"id": "POST-FC-OB-005", "text": "Checkpoints updated if necessary via update_checkpoints."},
          {"id": "POST-FC-OB-006", "text": "Unrealized justification and finality computed via compute_pulled_up_tip."}
        ]
      }
    ],
    "metadata": {
      "timestamp": "1770265501",
      "extraction_method": "web_fetch",
      "worker_id": 6,
      "batch_id": "B7"
    }
  }
]

